3:import java.math.BigDecimal;
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { Rates } from '../rates/rates';
import { Settings, SettingsStore } from '../settings/settings';
import { Delegation } from '../delegation/delegation';
import { Holidays } from '../holidays/holidays';
import { VoidReasons } from '../void-reasons/void-reasons';
import { ClaimTemplates } from '../claim-templates/claim-templates';
import { Pools } from '../pools/pools';
import { AuditViewer } from '../audit-viewer/audit-viewer';
import { PlanStore } from '../plans/plans';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People, Rates, Settings, Delegation, Holidays, VoidReasons, ClaimTemplates, Pools, AuditViewer],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form (submit)="load($event)" aria-label="Load sheet">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (session.sheetId(); as id) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ session.sheetToday() }}</strong></p>
        <p>Archived: <strong data-testid="sheet-archived">{{ session.sheetArchived() ? 'yes' : 'no' }}</strong></p>
        <p>Parent sheet: <strong data-testid="sheet-parent">{{ settings.parent() ?? '' }}</strong></p>

        <form (submit)="saveToday($event)" aria-label="Change today">
          <label for="sheet-today">New today</label>
          <input
            id="sheet-today"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>

        <form (submit)="cloneSheet($event)" aria-label="Clone sheet">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneInput()"
            (input)="cloneInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
        </form>
        <p>Cloned to: <strong data-testid="sheet-cloned-to">{{ clonedTo() ?? '' }}</strong></p>

        <p>As of: <strong data-testid="sheet-asof">{{ session.sheetAsOf() ?? '' }}</strong></p>
        <form (submit)="setAsOf($event)" aria-label="Show the sheet as of a date">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as err) {
            <p role="alert" data-testid="asof-error">{{ err }}</p>
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the active sheet's audit lines exactly as the file holds them, newest first. With a name in the
// filter, only the lines about that person (name= or person= that name, case and surrounding spaces ignored), then
// those on the sheet's descendants (sheets by id, each newest first), then, for a person transferred to this sheet, the lines about them from the sheet they came from.
@Component({
  selector: 'app-audit-viewer',
  template: `
    <section aria-label="Audit">
      <h2>Audit</h2>
      <form (submit)="show($event)" aria-label="Show the audit">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show audit</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>

      <ol aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditViewer {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly lines = signal<readonly string[]>([]);
  protected readonly filter = signal('');
  protected readonly error = signal<string | null>(null);
  // Each press is numbered, so only the latest one's answer shows.
  private press = 0;

  constructor() {
    // A newly loaded sheet starts with the list empty.
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.press++;
        this.error.set(null);
        this.lines.set([]);
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    this.error.set(null);
    this.lines.set([]);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const press = ++this.press;
    try {
      const l = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, {
          params: { name: this.filter() },
        }),
      );
      if (press === this.press) this.lines.set(l);
    } catch {
      if (press === this.press) this.error.set('Could not read the audit.');
    }
  }
}

